import{_ as i,c as a,o as l,ag as o}from"./chunks/framework.C86mscM5.js";const p=JSON.parse('{"title":"容器","description":"","frontmatter":{},"headers":[],"relativePath":"devops/containers/index.md","filePath":"devops/containers/index.md","lastUpdated":1788689791000}'),t={name:"devops/containers/index.md"};function r(d,e,n,c,s,h){return l(),a("div",null,e[0]||(e[0]=[o('<h1 id="容器" tabindex="-1">容器 <a class="header-anchor" href="#容器" aria-label="Permalink to &quot;容器&quot;">​</a></h1><p>容器把应用及其运行依赖封装为可分发制品。OCI 定义镜像与运行时规范，Docker 和 Podman 提供常用构建、运行与管理能力。</p><h2 id="从开发到生产" tabindex="-1">从开发到生产 <a class="header-anchor" href="#从开发到生产" aria-label="Permalink to &quot;从开发到生产&quot;">​</a></h2><ol><li>使用可复现的构建生成镜像。</li><li>以 Commit SHA、版本和 digest 标识镜像。</li><li>生成 SBOM，完成漏洞扫描和签名。</li><li>推送到受控镜像仓库。</li><li>以非 root、资源受限和只读文件系统运行。</li><li>将日志输出到标准输出，并提供健康检查。</li></ol><h2 id="构建" tabindex="-1">构建 <a class="header-anchor" href="#构建" aria-label="Permalink to &quot;构建&quot;">​</a></h2><ul><li>使用多阶段构建，只将运行所需文件复制到最终镜像。</li><li>固定基础镜像版本；生产部署记录 digest，避免漂移。</li><li>使用 <code>.dockerignore</code> 排除 Git、依赖缓存、测试结果和本地 Secret。</li><li>合理利用 BuildKit 缓存挂载，避免为了缓存牺牲正确性。</li><li>不在 <code>ARG</code>、<code>ENV</code>、<code>COPY</code> 或镜像历史中保存凭据。</li></ul><h2 id="运行" tabindex="-1">运行 <a class="header-anchor" href="#运行" aria-label="Permalink to &quot;运行&quot;">​</a></h2><ul><li>创建专用非 root 用户，避免 <code>--privileged</code>。</li><li>设置 CPU、内存和进程数限制；处理终止信号并设置停止宽限期。</li><li>根文件系统尽量只读，把持久数据放入 Volume 或外部存储。</li><li>提供存活、就绪和启动检查，但避免检查本身依赖过多外部服务。</li><li>日志写入标准输出/错误，由平台收集；不要无限增长本地日志文件。</li></ul><h2 id="compose-边界" tabindex="-1">Compose 边界 <a class="header-anchor" href="#compose-边界" aria-label="Permalink to &quot;Compose 边界&quot;">​</a></h2><p>Compose 适合本地开发、集成测试和简单单机服务。生产环境使用时仍需自行解决高可用、调度、Secret、滚动发布、集中日志和备份。</p><h2 id="发布检查" tabindex="-1">发布检查 <a class="header-anchor" href="#发布检查" aria-label="Permalink to &quot;发布检查&quot;">​</a></h2><ul><li>镜像能否追溯到 Commit、流水线和 SBOM？</li><li>是否仅包含运行依赖，且无高危可利用漏洞？</li><li>容器在非 root、只读和资源限制下能否正常运行？</li><li>退出、重启和依赖短暂不可用时行为是否符合预期？</li></ul>',12)]))}const u=i(t,[["render",r]]);export{p as __pageData,u as default};
